			"adjacent intervals [0,5] and [6,10]",
		},
		{
			interval16{start: 0, length: 5},  // [0,5]
			interval16{start: 7, length: 4},  // [7,11]
			"separated intervals [0,5] and [7,11]",
		},
		{
			interval16{start: 0, length: 5},  // [0,5]
			interval16{start: 3, length: 4},  // [3,7]
			"overlapping intervals [0,5] and [3,7]",
		},
		{
			interval16{start: 5, length: 2},  // [5,7]
			interval16{start: 0, length: 3},  // [0,3]
			"non-overlapping out-of-order intervals [5,7] and [0,3]",
		},
	}

	for _, tc := range testCases {
		result := canMerge16(tc.a, tc.b)
		fmt.Printf("%s: canMerge16 = %t\n", tc.desc, result)
		fmt.Printf("  a=[%d,%d], b=[%d,%d]\n", tc.a.start, tc.a.last(), tc.b.start, tc.b.last())
		fmt.Printf("  a.last()+1=%d, b.start()=%d, a.last()+1 < b.start(): %t\n", 
			tc.a.last()+1, tc.b.start(), int(tc.a.last())+1 < int(tc.b.start()))
		fmt.Printf("  b.last()+1=%d, a.start()=%d, b.last()+1 >= a.start(): %t\n", 
			tc.b.last()+1, tc.a.start(), int(tc.b.last())+1 >= int(tc.a.start()))
		fmt.Println()
	}
}
EOF
```

